-- ----------------------------
-- Table structure for tm_certificate
-- ----------------------------
DROP TABLE IF EXISTS `tm_certificate`;
CREATE TABLE `tm_certificate`  (
  `id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证书ID',
  `parent_id` varchar(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '父证书ID（自关联，顶级为NULL）',
  `short_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '编号',
  `certificate_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书名称',
  `certificate_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书级别：1级/2级/3级',
  `expire_year` int NULL DEFAULT NULL COMMENT '过期年限：1、2、3',
  `certificate_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '数字证书价格',
  `physical_certificate_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '物理/实体证书价格',
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '状态：有效/无效/已过期',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '证书描述',
  `pdf_ribbon_main_color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书PDF正面主彩带颜色，十六进制色值，如#FFD400',
  `pdf_ribbon_side_color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书PDF正面副彩带颜色，十六进制色值，如#FFC400',
  `pdf_front_certificate_icon_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书PDF正面证书类型图标URL',
  `pdf_back_content_image_url` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书PDF背面主体内容图片URL',
  `pdf_front_img` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书PDF正面整图模板URL',
  `pdf_back_img` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '证书PDF背面整图模板URL',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '证书表（递归自关联 3级别）' ROW_FORMAT = Dynamic;

